import gym
import highway_env
from arguments import get_common_args, get_mixer_args
from runner import Runner
controlled_vehicles = 4
view = 5

def make_env():
    env = gym.make("intersection-multi-agent-v0")
    config = {
        "observation": {
            "type": "MultiAgentObservation",
            "observation_config": {
                "vehicles_count": view,
                "features": ["presence", "x", "y", "vx", "vy", "heading"],
                "features_range": {
                    "x": [-100, 100],
                    "y": [-100, 100],
                    "vx": [-20, 20],
                    "vy": [-20, 20],
                },
                "type": "Kinematics",
                "absolute": True,
                "normalize": False,
            }
        },
        "action": {
            "type": "MultiAgentAction",
            "action_config": {
                "type": "DiscreteMetaAction",
                "lateral": False,
                "longitudinal": True,
                "target_speeds": [3, 6, 9]
            }
        },
        "controlled_vehicles": controlled_vehicles,
        'simulation_frequency': 10,
        "initial_vehicle_count": 0, ##5
        "spawn_probability": 0.00, ##0.01
        'policy_frequency': 5,
        "destination": "o1",
        # "initial_vehicle_count": 0,
        # "spawn_probability": 0.0,
        "screen_width": 1280,
        "screen_height": 800,
        "centering_position": [0.5, 0.8],
        "scaling": 5 * 1,
        "duration": 100 # [s]
    }
    env.config.update(config)
    return env

if __name__ == '__main__':

        args = get_common_args()
        args = get_mixer_args(args)

        env = make_env()

        args.n_actions = 3
        args.n_agents = 4
        args.state_shape = 120
        args.obs_shape = 30
        args.episode_limit = 250

        runner = Runner(env, args)
        if not args.evaluate:
            runner.run(1)
        else:
            win_rate, _, _, _,_ = runner.evaluate()
            print('The win rate of {} is  {}'.format(args.alg, win_rate))
